const year = new Date().getUTCFullYear();
const emailTo = 'dbertona@powersolution.es';
const companies = [
  { slug: 'psi', companyName: 'Power Solution Iberia SL', companyId: 'ca9dc1bf-54ee-ed11-884a-000d3a455d5b' },
  { slug: 'pslab', companyName: 'PS LAB CONSULTING SL', companyId: '656f8f0e-2bf4-ed11-8848-000d3a4baf18' },
];
return companies.map(c => ({ json: { ...c, year, emailTo } }));

const year = Number($json.year);
const companyName = $json.companyName;
const companyId = $json.companyId;
const env = (($env.BC_ENVIRONMENT && String($env.BC_ENVIRONMENT).trim()) || 'Production');
const base = 'https://api.businesscentral.dynamics.com/v2.0/a18dc497-a8b8-4740-b723-65362ab7a3fb/'
  + env + '/api/Power_Solution/PS_API/v2.0/companies(' + companyId + ')';

// Tipo R cerrado: movimientosProyectosMes Ingresos (year texto)
const movUrl = base + "/movimientosProyectosMes"
  + "?$select=invoice,year,descripcionCA,job"
  + "&$filter=year%20eq%20'" + year + "'%20and%20descripcionCA%20eq%20'Ingresos'";

// Tipo R abierto (cert): movimientosProyectos Ingresos + tieneCertificacion (igual path 004)
const certUrl = base + "/movimientosProyectos"
  + "?$select=jobNo,year,month,totalPrice,descripcion,tieneCertificacion,documentNo,no"
  + "&$filter=year%20eq%20'" + year + "'%20and%20descripcion%20eq%20'Ingresos'%20and%20tieneCertificacion%20eq%20true";

// Tipo P sync: planificacionMes bruto (year entero). SUM sin Distinct (2026-08-07).
const planifUrl = base + "/planificacionMes"
  + "?$select=job,year,month,invoice,cost,nr,estado,budgetDateYear,budgetDateMonth,descripcionCA"
  + "&$filter=year%20eq%20" + year;

const cerradosUrl = base + "/mesesCerrados"
  + "?$select=job,fecha";

return [{ json: {
  year, companyName, companyId, slug: $json.slug,
  movUrl, certUrl, planifUrl, cerradosUrl,
  emailTo: $json.emailTo || 'dbertona@powersolution.es',
}}];

const input = $input.all();
const meta = $('Build BC URLs').first().json;
let sum = 0;
let count = 0;
for (const it of input) {
  const raw = it?.json ?? {};
  if (raw.error || raw.statusCode >= 400) continue;
  const src = raw?.body ?? raw;
  const chunk = Array.isArray(src.value) ? src.value : (Array.isArray(src) ? src : []);
  for (const r of chunk) {
    const inv = Number(r.invoice ?? 0);
    if (!Number.isFinite(inv)) continue;
    sum += inv;
    count += 1;
  }
}
return [{ json: {
  ...meta,
  bc_r_sum: Math.abs(sum),
  bc_r_count: count,
}}];

const input = $input.all();
const meta = $('Sum Movimientos BC').first().json;
const allowed = new Set(['Planning', 'Quote', 'Open', 'Completed', 'Lost']);
const toNum = (v) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};
let sum = 0;
let count = 0;
for (const it of input) {
  const raw = it?.json ?? {};
  if (raw.error || raw.statusCode >= 400) continue;
  const src = raw?.body ?? raw;
  const chunk = Array.isArray(src.value) ? src.value : (Array.isArray(src) ? src : []);
  for (const r of chunk) {
    const job = String(r.job ?? '').trim();
    if (!job || job.startsWith('PP') || job.startsWith('PY')) continue;
    const status = String(r.estado ?? r.status ?? '').trim();
    if (!allowed.has(status)) continue;
    const year = Number(r.year ?? 0) || 0;
    const month = Number(r.month ?? 0) || 0;
    if (!year || !month) continue;
    const budgetYear = toNum(r.budgetDateYear);
    const budgetMonth = toNum(r.budgetDateMonth);
    // Misma regla Transform 004: si hay budgetDate, exigir year==budgetYear y month>=budgetMonth
    if (budgetYear !== 0 && (year !== budgetYear || month < budgetMonth)) continue;
    const inv = toNum(r.invoice);
    sum += inv;
    count += 1;
  }
}
return [{ json: {
  ...meta,
  bc_p_planif_sum: Number(sum.toFixed(2)),
  bc_p_planif_count: count,
}}];

const input = $input.all();
const meta = $('Sum Planificacion BC').first().json;
let count = 0;
const skip = (j) => {
  const s = String(j || '').trim();
  return s.startsWith('PP') || s.startsWith('PY');
};
const seen = new Set();
for (const it of input) {
  const raw = it?.json ?? {};
  if (raw.error || raw.statusCode >= 400) continue;
  const src = raw?.body ?? raw;
  const chunk = Array.isArray(src.value) ? src.value : (Array.isArray(src) ? src : []);
  for (const r of chunk) {
    const job = String(r.job ?? '').trim();
    const fecha = String(r.fecha ?? '').trim();
    if (!job || !fecha || skip(job) || fecha.startsWith('0001')) continue;
    const key = job + '|' + fecha;
    if (seen.has(key)) continue;
    seen.add(key);
    count += 1;
  }
}
return [{ json: { ...meta, bc_cerrados_count: count } }];

const input = $input.all();
const meta = $('Sum MesesCerrados BC').first().json;
const year = Number(meta.year) || 0;
const toNum = (v) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};

// Meses cerrados BC → set job|year|month (misma exclusión que Upsert Cert Open 004)
const closed = new Set();
try {
  for (const it of ($items('BC MesesCerrados') || [])) {
    const raw = it?.json ?? {};
    if (raw.error || raw.statusCode >= 400) continue;
    const src = raw?.body ?? raw;
    const chunk = Array.isArray(src.value) ? src.value : (Array.isArray(src) ? src : []);
    for (const r of chunk) {
      const job = String(r.job ?? '').trim();
      const fecha = String(r.fecha ?? '').trim();
      if (!job || !fecha || fecha.startsWith('0001')) continue;
      if (job.startsWith('PP') || job.startsWith('PY')) continue;
      const d = new Date(fecha.includes('T') ? fecha : fecha + 'T00:00:00Z');
      if (Number.isNaN(d.getTime())) continue;
      const y = d.getUTCFullYear();
      const m = d.getUTCMonth() + 1;
      if (y === year) closed.add(job + '|' + y + '|' + m);
    }
  }
} catch (e) {}

// Certificaciones en meses ABIERTOS (provisional R). totalPrice negativo → ABS.
let certSum = 0;
let certCount = 0;
let certSkippedClosed = 0;
for (const it of input) {
  const raw = it?.json ?? {};
  if (raw.error || raw.statusCode >= 400) continue;
  const src = raw?.body ?? raw;
  const chunk = Array.isArray(src.value) ? src.value : (Array.isArray(src) ? src : []);
  for (const r of chunk) {
    const job = String(r.jobNo ?? r.JobNo ?? r.job ?? '').trim();
    if (!job || job.startsWith('PP') || job.startsWith('PY')) continue;
    const y = Number(r.year ?? 0) || 0;
    const m = Number(r.month ?? 0) || 0;
    if (y !== year || !m) continue;
    const concepto = String(r.descripcion ?? r.Descripcion ?? '').trim();
    if (concepto && concepto !== 'Ingresos') continue;
    const key = job + '|' + y + '|' + m;
    if (closed.has(key)) { certSkippedClosed += 1; continue; }
    // Mismo signo que Transform Cert Open: totalPrice * -1
    const inv = toNum(r.totalPrice ?? r.TotalPrice) * -1;
    certSum += inv;
    certCount += 1;
  }
}

const movSum = toNum(meta.bc_r_sum); // ya ABS desde Sum Movimientos
const bc_r_total = Number((movSum + Math.abs(certSum)).toFixed(2));

return [{ json: {
  ...meta,
  bc_r_mov_sum: movSum,
  bc_r_cert_open_sum: Number(Math.abs(certSum).toFixed(2)),
  bc_r_cert_open_count: certCount,
  bc_r_cert_skipped_closed: certSkippedClosed,
  bc_r_sum: bc_r_total, // total alineado con Analytics ledger Ingresos
}}];

const meta = $('Sum Cert Open BC').first().json;
const rows = $input.all().map(i => i.json);
const a = rows[0] || {};

const num = (v) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};

const an_r = Math.abs(num(a.r_sum));
const an_p_planif = num(a.p_planif_sum);
const an_cerrados = num(a.cerrados_count);
const an_budget0 = num(a.budget0_past_count);
const planif_actual = Math.abs(num(a.planificacion_actual));
const lastSync = a.last_sync_at ? new Date(a.last_sync_at) : null;
const hoursSinceSync = lastSync ? (Date.now() - lastSync.getTime()) / 3600000 : 999;

const checks = [];
const push = (check_name, bc, an, tol, kind='abs', detailsExtra={}) => {
  const delta = Number((bc - an).toFixed(2));
  let status = 'ok';
  if (kind === 'count' && Math.abs(delta) > tol) status = 'fail';
  if (kind === 'abs' && Math.abs(delta) > tol) status = 'fail';
  if (kind === 'signal' && an > tol) status = 'fail';
  if (kind === 'fresh' && an > tol) status = 'warn';
  if (kind === 'cerrados') {
    const base = Math.max(Math.abs(bc), Math.abs(an), 1);
    const pct = Math.abs(delta) / base;
    if (pct > 0.05) status = 'fail';
    else if (Math.abs(delta) > tol) status = 'warn';
  }
  if (kind === 'info') status = 'ok';
  checks.push({
    company_name: meta.companyName,
    year: meta.year,
    check_name,
    bc_value: bc,
    analytics_value: an,
    delta,
    status,
    details: { slug: meta.slug, kind, ...detailsExtra },
  });
};

// Tipo R = MovimientosMes (cerrados) + Cert Open (abiertos). Misma composición que Analytics ledger.
push(
  'tipo_r_sum',
  Number(num(meta.bc_r_sum).toFixed(2)),
  Number(an_r.toFixed(2)),
  0.5,
  'abs',
  {
    bc_r_mov_sum: meta.bc_r_mov_sum,
    bc_r_cert_open_sum: meta.bc_r_cert_open_sum,
  }
);

push(
  'tipo_p_planif_sum',
  Number(num(meta.bc_p_planif_sum).toFixed(2)),
  Number(an_p_planif.toFixed(2)),
  0.5,
  'abs'
);

push('meses_cerrados_count', meta.bc_cerrados_count, an_cerrados, 50, 'cerrados');
push('budget0_past_with_invoice', 0, an_budget0, 0, 'signal');
push('sync_freshness_hours', 26, Number(hoursSinceSync.toFixed(1)), 26, 'fresh');
push('planificacion_actual_p_plus_r', planif_actual, planif_actual, 0, 'info');

const hasFail = checks.some(c => c.status === 'fail');
const hasWarn = checks.some(c => c.status === 'warn');
const overall = hasFail ? 'fail' : (hasWarn ? 'warn' : 'ok');

return [{ json: {
  companyName: meta.companyName,
  year: meta.year,
  emailTo: meta.emailTo,
  overall,
  checks,
  hasDiff: hasFail || hasWarn,
}}];

const d = $json;
const alert = d.hasDiff ? 'true' : 'false';
return (d.checks || []).map(c => ({
  json: {
    company_name: c.company_name,
    year: c.year,
    check_name: c.check_name,
    bc_value: c.bc_value === null || c.bc_value === undefined ? '' : String(c.bc_value),
    analytics_value: c.analytics_value === null || c.analytics_value === undefined ? '' : String(c.analytics_value),
    delta: c.delta === null || c.delta === undefined ? '' : String(c.delta),
    status: c.status,
    details: JSON.stringify(c.details || {}),
    alert_sent: alert,
    // pass-through for later aggregate
    _overall: d.overall,
    _hasDiff: d.hasDiff,
    _companyName: d.companyName,
    _emailTo: d.emailTo,
    _checks: d.checks,
  }
}));

const items = $input.all();
if (!items.length) return [];
const first = items[0].json;
return [{ json: {
  companyName: first._companyName,
  year: first.year,
  emailTo: first._emailTo,
  overall: first._overall,
  hasDiff: first._hasDiff,
  checks: first._checks,
}}];

const rows = $input.all().map(i => i.json).filter(r => r && r.check_name);
if (!rows.length) return [];

const esc = (s) => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const fmt = (n) => {
  if (n === null || n === undefined || n === '') return '';
  const x = Number(n);
  return Number.isFinite(x) ? x.toLocaleString('es-ES', { maximumFractionDigits: 2 }) : String(n);
};

let body = '';
for (const c of rows) {
  body += `<tr>
    <td style="padding:6px;border:1px solid #ddd;">${esc(c.company_name)}</td>
    <td style="padding:6px;border:1px solid #ddd;">${esc(c.check_name)}</td>
    <td style="padding:6px;border:1px solid #ddd;text-align:right;">${esc(fmt(c.bc_value))}</td>
    <td style="padding:6px;border:1px solid #ddd;text-align:right;">${esc(fmt(c.analytics_value))}</td>
    <td style="padding:6px;border:1px solid #ddd;text-align:right;">${esc(fmt(c.delta))}</td>
    <td style="padding:6px;border:1px solid #ddd;">${esc(c.status)}</td>
  </tr>`;
}

const when = new Date().toISOString().slice(0,10);
const html = `<!DOCTYPE html><html><body style="font-family:Segoe UI,sans-serif;color:#333;">
<p style="margin:0 0 16px;font-size:13px;color:#c0392b;font-weight:600;">Alerta Health Check Analytics vs BC (workflow 021)</p>
<p>Se detectaron discrepancias CRÍTICAS el <strong>${esc(when)}</strong> (${rows.length} checks).</p>
<table style="border-collapse:collapse;width:100%;max-width:900px;">
<thead><tr style="background:#f0f0f0;">
<th style="padding:6px;border:1px solid #ddd;text-align:left;">Empresa</th>
<th style="padding:6px;border:1px solid #ddd;text-align:left;">Check</th>
<th style="padding:6px;border:1px solid #ddd;text-align:right;">BC</th>
<th style="padding:6px;border:1px solid #ddd;text-align:right;">Analytics</th>
<th style="padding:6px;border:1px solid #ddd;text-align:right;">Delta</th>
<th style="padding:6px;border:1px solid #ddd;text-align:left;">Status</th>
</tr></thead>
<tbody>${body}</tbody></table>
<p style="font-size:12px;color:#888;margin-top:16px;">
Solo se alerta por fallos críticos (Real/Planificación sync desalineados, plan sin versionar en meses cerrados, o >5% en meses cerrados). Diferencias menores (warn) quedan solo en <code>analytics_health_log</code> para revisión semanal. Acciones tipicas: webhook 004 (psi|pslab), revisar meses cerrados / budget_date_year.
</p>
</body></html>`;

return [{ json: {
  to: 'dbertona@powersolution.es',
  subject: `[Analytics 021] Discrepancia BC vs Analytics — ${when}`,
  html,
}}];
